def gen(rng):
    digs = '0123456789'
    letters = 'abcdefghijklmnopqrstuvwxyz'

    def rd(n):
        return ''.join(rng.choice(digs) for _ in range(n))

    def word():
        return ''.join(rng.choice(letters) for _ in range(rng.randint(1, 8)))

    def card(k):
        if k == 0:
            return '4' + rd(rng.choice([12, 15]))
        if k == 1:
            return rng.choice(['34', '37']) + rd(13)
        if k == 2:
            return str(rng.randint(51, 55)) + rd(14)
        if k == 3:
            return str(rng.randint(2221, 2720)) + rd(12)
        if k == 4:
            return '4' + rd(rng.choice([11, 13, 14, 16]))
        if k == 5:
            return rng.choice(['33', '35', '36', '38']) + rd(13)
        if k == 6:
            return rng.choice(['34', '37']) + rd(rng.choice([12, 14]))
        if k == 7:
            return rng.choice(['50', '56', '57', '60']) + rd(14)
        if k == 8:
            return rng.choice(['2220', '2721', '2800', '1999']) + rd(12)
        if k == 9:
            return rng.choice(['51', '55', '2221', '2720']) + rd(rng.choice([11, 12, 13, 14, 15]))
        if k == 10:
            return rng.choice(['2221', '2720', '2500']) + rd(12)
        if k == 11:
            return rd(rng.randint(1, 12))
        return rd(rng.randint(13, 19))

    def tok(fancy):
        if rng.random() < 0.25:
            return word()
        c = card(rng.randint(0, 12))
        if fancy:
            if rng.random() < 0.2:
                c = '-'.join(c[i:i + 4] for i in range(0, len(c), 4))
            if rng.random() < 0.12:
                c = rng.choice(['id', 'ref_', 'n.']) + c
            if rng.random() < 0.08:
                c += rng.choice(['x', '.', '_'])
        return c

    def fmt(mode, toks):
        return str(mode) + '\n' + str(len(toks)) + '\n' + ' '.join(toks)

    tests = [
        fmt(1, ['1234567890123456', 'is', 'a', 'number']),
        fmt(2, ['1234567890123456', '4111111111111', '371449635398431', '5600000000000000']),
        fmt(1, ['ref-4111-1111-1111-1111', '123456789012', 'x']),
        fmt(1, ['1234567890123']),
        fmt(1, ['123456789012']),
        fmt(1, ['12345678901234567']),
        fmt(2, ['4111111111111']),
        fmt(2, ['2221000000000009', '2720999999999999', '2220999999999999', '2721000000000000']),
        fmt(2, ['5100000000000000', '5500000000000000', '5000000000000000', '5600000000000000']),
        fmt(2, ['340000000000000', '370000000000000', '350000000000000', '34000000000000', '3400000000000000']),
        fmt(2, ['abc', 'a1b2c3d4e5f6g7h8', '4a111111111111b1']),
    ]
    for _ in range(40):
        mode = rng.choice([1, 2])
        m = rng.randint(1, 9)
        tests.append(fmt(mode, [tok(True) for _ in range(m)]))
    for mode in (1, 2):
        toks = [tok(False) for _ in range(100000)]
        toks[rng.randint(0, 99999)] = ''.join(rng.choice('ab12') for _ in range(30))
        tests.append(fmt(mode, toks))
    toks = [card(rng.randint(0, 3)) for _ in range(100000)]
    tests.append(fmt(2, toks))
    return tests
